local root=app.params.root
local banks={{name="hull",n=16,fps=16},{name="hull_aura",n=16,fps=16},{name="core",n=32,fps=16},{name="core_hit",n=1,fps=16},{name="core_aura",n=16,fps=16},{name="core_wreck",n=1,fps=16},{name="gun",n=78,fps=16},{name="gun_hit",n=6,fps=16},{name="gun_wreck",n=3,fps=16},{name="gun_aura",n=16,fps=16},{name="pod0",n=32,fps=16},{name="pod0_hit",n=1,fps=16},{name="pod0_wreck",n=1,fps=16},{name="pod0_aura",n=16,fps=16},{name="pod1",n=32,fps=16},{name="pod1_hit",n=1,fps=16},{name="pod1_wreck",n=1,fps=16},{name="pod1_aura",n=16,fps=16},{name="wind_beam",n=28,fps=24}}
for _,b in ipairs(banks)do local first=Image{fromFile=root.."/frames/"..b.name.."/000.png"};local s=Sprite(first.width,first.height,ColorMode.RGB);s.layers[1].name=b.name.." / fixed native cells";for i=0,b.n-1 do if i>0 then s:newEmptyFrame(i+1)end;local im=Image{fromFile=root.."/frames/"..b.name.."/"..string.format("%03d",i)..".png"};s:newCel(s.layers[1],i+1,im,Point(0,0));s.frames[i+1].duration=1/b.fps end;s:saveAs(root.."/"..b.name..".aseprite");s:close()end
